for (const id of ['run-6779vs', 'run-Vtblhp']) {
 const dir = 'verification/evidence/' + id;
 const r = JSON.parse(fs.readFileSync(dir + '/report.json'));
 assert.equal(r.passed, true);
 assert.equal(r.cleanup.ownedProcessStopped, true);
 assert.deepEqual(r.exit, {code: 0, signal: null});
 assert.throws(() => process.kill(r.pid, 0), {code: 'ESRCH'});
 assert.equal(r.observations['sum7+5'].body.result, 12);
 assert.equal(r.observations.export.status, 404);
